package io.knowledgebrain.gateway;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.*;
class SubmissionProxyTest {
 @Test void forwardsIntentAndVersionButNotCallerAuthority()throws Exception{var f=new GroupProxyTest();f.init();String root="/api/groups/"+f.id+"/studies/"+f.id+"/assignments/"+f.id+"/submissions";var r=f.request("POST",root);r.addHeader("Idempotency-Key","a".repeat(32));r.addHeader("If-Match","\"su0\"");r.addHeader("X-Principal-Id",f.id);r.addHeader("Authorization","Bearer spoof");r.setContent("{}".getBytes());f.proxy.proxy(r);verify(f.transport).send(eq(new GatewayRoute("collaboration",root)),eq("POST"),argThat(h->h.get("Idempotency-Key").equals(List.of("a".repeat(32)))&&h.get("If-Match").equals(List.of("\"su0\""))&&!h.containsKey("Authorization")&&!h.containsKey("X-Principal-Id")),any());}
 @Test void catalogHistoryAndMineQueriesStayBoundedAndMissingKeyFails(){var f=new GroupProxyTest();assertDoesNotThrow(f::init);String root="/api/groups/"+f.id+"/studies/"+f.id+"/assignments/"+f.id+"/submissions";for(String q:List.of("authorId="+f.id,"limit=101","limit=1&limit=2","before=1")){var r=f.request("GET",root);r.setQueryString(q);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->f.proxy.proxy(r));}var mine=f.request("GET",root+"/mine");mine.setQueryString("limit=1");assertThrows(org.springframework.web.server.ResponseStatusException.class,()->f.proxy.proxy(mine));var missing=f.request("POST",root);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->f.proxy.proxy(missing));verifyNoInteractions(f.transport);}
}
